class Solution:
    def letterCasePermutation(self, s: str) -> List[str]:
        res = []
        def bt(i, path):
            if i == len(s):
                res.append(''.join(path))
                return
            if s[i].isalpha():
                bt(i+1, path + [s[i].lower()])
                bt(i+1, path + [s[i].upper()])
            else:
                bt(i+1, path + [s[i]])
        bt(0, [])
        return res

class Solution:
    def isBipartite(self, graph: List[List[int]]) -> bool:
        n = len(graph)
        color = [0] * n
        for i in range(n):
            if color[i]: continue
            queue = [i]
            color[i] = 1
            while queue:
                node = queue.pop(0)
                for nei in graph[node]:
                    if color[nei] == color[node]: return False
                    if not color[nei]:
                        color[nei] = -color[node]
                        queue.append(nei)
        return True

class Solution:
    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
        dist = [float('inf')] * n
        dist[src] = 0
        for _ in range(k + 1):
            tmp = dist[:]
            for u, v, w in flights:
                if dist[u] + w < tmp[v]:
                    tmp[v] = dist[u] + w
            dist = tmp
        return dist[dst] if dist[dst] != float('inf') else -1

