class Solution:
    def numMatchingSubseq(self, s: str, words: List[str]) -> int:
        from collections import defaultdict
        buckets = defaultdict(list)
        for w in words:
            buckets[w[0]].append(iter(w[1:]))
        count = 0
        for c in s:
            old = buckets[c]
