class Solution:
    def preimageSizeFZF(self, k: int) -> int:
        def zeros(n):
            count = 0
            while n:
                n //= 5
                count += n
            return count
        def lower(target):
            lo, hi = 0, 5 * target + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if zeros(mid) >= target: hi = mid
                else: lo = mid + 1
            return lo
        return lower(k + 1) - lower(k)

