class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        TOP = m * n
        parent = list(range(m * n + 1))
        size = [1] * (m * n + 1)
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb: return
            if size[ra] < size[rb]: ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
        def idx(r, c): return r * n + c
        A = [row[:] for row in grid]
        for r, c in hits: A[r][c] = 0
        for r in range(m):
            for c in range(n):
                if A[r][c]:
                    if r == 0: union(idx(r,c), TOP)
                    if r > 0 and A[r-1][c]: union(idx(r,c), idx(r-1,c))
                    if c > 0 and A[r][c-1]: union(idx(r,c), idx(r,c-1))
        res = [0] * len(hits)
        for k in range(len(hits)-1, -1, -1):
            r, c = hits[k]
            if grid[r][c] == 0: continue
            prev = size[find(TOP)]
            A[r][c] = 1
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n and A[nr][nc]: union(idx(r,c), idx(nr,nc))
            if r == 0: union(idx(r,c), TOP)
            cur = size[find(TOP)]
            res[k] = max(0, cur - prev - 1)
        return res

