class Solution:
    def expressiveWords(self, s: str, words: List[str]) -> int:
        def groups(w):
            res = []
            i = 0
            while i < len(w):
                j = i
                while j < len(w) and w[j] == w[i]: j += 1
                res.append((w[i], j - i))
                i = j
            return res
        sg = groups(s)
        count = 0
