class Solution:
    def largestSumOfAverages(self, nums: List[int], k: int) -> float:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n): prefix[i+1] = prefix[i] + nums[i]
        dp = [prefix[i+1]/(i+1) for i in range(n)]  # k=1
        for _ in range(k - 1):
            ndp = [0.0] * n
            for i in range(n):
                for j in range(i):
                    ndp[i] = max(ndp[i], dp[j] + (prefix[i+1]-prefix[j+1])/(i-j))
            dp = ndp
        return dp[n-1]

class Solution:
    def numBusesToDestination(self, routes: List[List[int]], source: int, target: int) -> int:
        if source == target: return 0
        from collections import defaultdict, deque
        stop2routes = defaultdict(set)
        for i, route in enumerate(routes):
            for stop in route:
                stop2routes[stop].add(i)
        visited_routes = set()
        visited_stops = {source}
        queue = deque([source])
        level = 0
        while queue:
            level += 1
            for _ in range(len(queue)):
                stop = queue.popleft()
                for route_id in stop2routes[stop]:
                    if route_id in visited_routes: continue
                    visited_routes.add(route_id)
                    for next_stop in routes[route_id]:
                        if next_stop == target: return level
                        if next_stop not in visited_stops:
                            visited_stops.add(next_stop)
                            queue.append(next_stop)
        return -1

class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        s = s[1:-1]
        def valid(part):
            res = []
            for i in range(1, len(part)+1):
                left, right = part[:i], part[i:]
                if (left == '0' or not left.startswith('0')) and not right.endswith('0'):
                    res.append(left + ('.' if right else '') + right)
            return res
        ans = []
        for i in range(1, len(s)):
            for x in valid(s[:i]):
                for y in valid(s[i:]):
                    ans.append(f'({x}, {y})')
        return ans

