class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:
        n = len(grid)
        label = [[0]*n for _ in range(n)]
        area = {0: 0}
        idx = 0
        def dfs(r, c, idx):
            label[r][c] = idx
            cnt = 1
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<n and 0<=nc<n and grid[nr][nc]==1 and label[nr][nc]==0:
                    cnt += dfs(nr, nc, idx)
            return cnt
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1 and label[i][j] == 0:
                    idx += 1
                    area[idx] = dfs(i, j, idx)
        res = max(area.values()) if area else 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0:
                    seen = set()
                    total = 1
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        ni, nj = i+dr, j+dc
                        if 0<=ni<n and 0<=nj<n and label[ni][nj] not in seen:
                            seen.add(label[ni][nj])
                            total += area.get(label[ni][nj], 0)
                    res = max(res, total)
        return res

class Solution:
    def uniqueLetterString(self, s: str) -> int:
        from collections import defaultdict
        index = defaultdict(lambda: [-1])
        for i, c in enumerate(s):
            index[c].append(i)
        for c in index:
            index[c].append(len(s))
        res = 0
        for c in index:
            arr = index[c]
            for i in range(1, len(arr) - 1):
                res += (arr[i] - arr[i-1]) * (arr[i+1] - arr[i])
        return res

