class Solution:
    def new21Game(self, n: int, k: int, maxPts: int) -> float:
        if k == 0 or n >= k + maxPts: return 1.0
        dp = [0.0] * (n + 1)
        dp[0] = 1.0
        wSum = 1.0
        for i in range(1, n + 1):
            dp[i] = wSum / maxPts
            if i < k: wSum += dp[i]
            if i >= maxPts: wSum -= dp[i - maxPts]
        return sum(dp[k:])

class Solution:
    def pushDominoes(self, dominoes: str) -> str:
        n = len(dominoes)
        forces = [0] * n
        f = 0
        for i in range(n):
            if dominoes[i] == 'R': f = n
            elif dominoes[i] == 'L': f = 0
            else: f = max(f - 1, 0)
            forces[i] += f
        f = 0
        for i in range(n-1, -1, -1):
            if dominoes[i] == 'L': f = n
            elif dominoes[i] == 'R': f = 0
            else: f = max(f - 1, 0)
            forces[i] -= f
        return ''.join('.' if x == 0 else ('R' if x > 0 else 'L') for x in forces)

class Solution:
    def numSimilarGroups(self, strs: List[str]) -> int:
        n = len(strs)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb: parent[ra] = rb
        def similar(a, b):
            diff = sum(1 for x, y in zip(a, b) if x != y)
            return diff <= 2
        for i in range(n):
            for j in range(i+1, n):
                if similar(strs[i], strs[j]):
                    union(i, j)
        return len(set(find(i) for i in range(n)))

class Solution:
    def numMagicSquaresInside(self, grid: List[List[int]]) -> int:
        def magic(r, c):
            vals = [grid[r+i][c+j] for i in range(3) for j in range(3)]
            if sorted(vals) != list(range(1, 10)): return False
            for i in range(3):
                if sum(grid[r+i][c:c+3]) != 15: return False
                if sum(grid[r+j][c+i] for j in range(3)) != 15: return False
            if grid[r][c]+grid[r+1][c+1]+grid[r+2][c+2] != 15: return False
            if grid[r][c+2]+grid[r+1][c+1]+grid[r+2][c] != 15: return False
            return True
        m, n = len(grid), len(grid[0])
        return sum(magic(i,j) for i in range(m-2) for j in range(n-2))
